const list = $input.first().json.rows || [];
const rows = list.map(p => {
  const sevColor = { urgent: '#dc2626', high: '#ea580c', medium: '#f59e0b', low: '#10b981' }[p.severity] || '#6b7280';
  const sevBadge = '<span style="background:' + sevColor + ';color:white;padding:2px 6px;border-radius:3px">' + (p.severity || '?').toUpperCase() + '</span>';
  const warrTxt = p.under_warranty ? '<span style="color:#10b981">en garantia (' + p.loe_period + 'a)</span>' : '<span style="color:#dc2626">fuera garantia</span>';
  const flags = [];
  if (p.days_open > 14) flags.push('+' + Math.round(p.days_open) + 'd sin avance');
  if (p.days_assigned !== null && p.days_assigned > 7) flags.push('+' + Math.round(p.days_assigned) + 'd asignada');
  if (p.severity === 'urgent') flags.push('URGENTE');
  const flagsStr = flags.length ? '<small style="color:#dc2626">' + flags.join(' &middot; ') + '</small>' : '<small style="color:#6b7280">-</small>';
  return '<tr>' +
    '<td>' + sevBadge + '</td>' +
    '<td><b>' + (p.project_name || '?') + '</b><br><small>' + warrTxt + '</small></td>' +
    '<td>' + (p.category || '?') + '<br><small>' + (p.responsible_trade || '?') + '</small></td>' +
    '<td>' + (p.status || '?') + '<br><small>' + (p.assigned_to || '— sin asignar') + '</small></td>' +
    '<td>' + Math.round(p.days_open) + 'd</td>' +
    '<td><small>' + (p.description || '').substring(0, 120) + '…</small></td>' +
    '<td>' + flagsStr + '</td>' +
    '</tr>';
}).join('');
const urgent = list.filter(p => p.severity === 'urgent').length;
const stale = list.filter(p => p.days_open > 14).length;
const html = '<h2>Postventa LOE — incidencias abiertas</h2>' +
  '<p>Total abiertas: <b>' + list.length + '</b> | Urgentes: <b style="color:#dc2626">' + urgent + '</b> | Sin avance &gt;14d: <b style="color:#f59e0b">' + stale + '</b></p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
  '<thead><tr style="background:#f3f4f6"><th>Sev.</th><th>Proyecto</th><th>Categoria/Gremio</th><th>Estado</th><th>Abierta</th><th>Descripcion</th><th>Alertas</th></tr></thead>' +
  '<tbody>' + rows + '</tbody></table>' +
  '<p style="font-size:11px;color:#6b7280">Asignar: POST /webhook/aftercare-assign con {incident_id, assigned_to}.<br>Resolver: POST /webhook/aftercare-resolve con {incident_id, resolution_notes}.</p>';
return [{ json: { html_body: html, count: list.length, urgent: urgent, stale: stale } }];

